// Writes src/connectors/catalog.generated.ts from connectors/catalog/*.connector.json, after the catalog passes
// the same checks CI runs (connectors/tools/check.mjs). The generated file is committed so Studio builds without
// the repository root; regenerate it after any catalog change:
//
//   node scripts/sync-connectors.mjs            # strict: any finding stops the build
//   node scripts/sync-connectors.mjs --partial  # development: bundle only the manifests that pass, say which were left out

import { writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repo = resolve(here, '../../../..')
const check = await import(pathToFileURL(join(repo, 'connectors/tools/check.mjs')).href)

const partial = process.argv.includes('--partial')
let entries = check.loadCatalog()
let findings = check.checkAll(entries)
if (findings.length && partial) {
  const bad = new Set(findings.map((f) => f.split(':')[0]))
  console.warn(`--partial: leaving out ${bad.size} manifest(s) with findings: ${[...bad].join(', ')}`)
  entries = entries.filter((e) => !bad.has(e.file))
  findings = check.checkAll(entries)
}
if (findings.length) {
  for (const f of findings) console.error(f)
  console.error(`\n${findings.length} finding(s); the catalog must pass connectors/tools/check.mjs before it is bundled`)
  process.exit(1)
}

const manifests = entries.map((e) => e.manifest).sort((a, b) => a.name.localeCompare(b.name, 'en'))
const header = `// Generated by scripts/sync-connectors.mjs from connectors/catalog/*.connector.json; do not edit.
// ${manifests.length} connectors, ${manifests.reduce((n, m) => n + m.operators.length, 0)} operators. Each passed connectors/tools/check.mjs.

import type { ConnectorManifest } from './types'

`
writeFileSync(join(here, '../src/connectors/catalog.generated.ts'), header + `export const CATALOG: ConnectorManifest[] = ${JSON.stringify(manifests, null, 1)}\n`)
console.log(`wrote src/connectors/catalog.generated.ts (${manifests.length} connectors)`)
